"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'The a vintage locket Summer', 'author': 'Signature original', 'genre': 'Holiday Romance', 'chapters': [{'n': 1, 'title': 'Homecoming', 'text': "Lucy Fairbanks hadn't meant to come back to the lakeside village. The city had been fine — fine in the way a waiting room is fine. But the letter about the old house, and a vintage locket tucked inside it, had pulled her home like a tide.\n\nThe house was smaller than memory and larger than grief. In the attic, under a quilt, Lucy Fairbanks found a vintage locket — and with it, the whole of her seventeenth summer came back in a rush.\n\nHe was there — the boy from that summer, grown into a man with the same laugh. Time folded. Lucy Fairbanks's heart, so carefully guarded, did something reckless: it hoped."}, {'n': 2, 'title': 'The Thing Remembered', 'text': "her overbearing mother — the reason she'd left, the shadow over it all — was still there, in the past where it belonged. Lucy Fairbanks felt it loosen its grip. second chances are real, she thought. Maybe. Just maybe.\n\nHe found her at the bookshop, reaching for the same novel. Their hands touched. The whole shop seemed to hold its breath. 'You came back,' he said, and it wasn't a question, it was a prayer answered.\n\nThey talked until the shop closed, until the streetlights came on in the lakeside village. Seventeen years of almosts poured out: the almost-letters, the almost-calls, the life they'd almost shared."}, {'n': 3, 'title': 'Complications', 'text': "Of course it couldn't be simple. her overbearing mother reappeared — older, smoother, with apologies like gift wrap. 'I've changed,' her overbearing mother said, and for an hour Lucy Fairbanks almost believed it.\n\nher best friend Jess was blunt: 'People don't change. They just get better at hiding.' But Lucy Fairbanks had changed — hadn't she? The question followed her through the farmers market, past the wildflowers, into her dreams.\n\na vintage locket sat on her dresser, accusing and comforting by turns. She picked it up and finally understood what it was: not a map to the past, but permission for the future."}, {'n': 4, 'title': 'The Choice', 'text': "She found him at the shore, where it started. 'I choose,' she said, breathless, 'the thing that scares me. I choose you. I've always chosen you — I just took seventeen years to say it.'\n\nher best friend Jess cried at the news and denied it. The whole of the lakeside village seemed to conspire in their happiness: the bookshop stayed open late, the bakery made a cake, the wildflowers bloomed on schedule.\n\nHe laughed through tears, the same laugh, and the sunset did its thing, and the lakeside village held its breath again. This time nobody interrupted. This time they stayed."}, {'n': 5, 'title': 'The Promise', 'text': "Late that night, on the shore, they stood where the boy and girl had stood. 'We made it,' he said. 'We were always going to,' she said, and believed it, the heart knowing first.\n\nHe proposed with a vintage locket — fitting, her best friend Jess said, since it started everything. Lucy Fairbanks said yes before he finished asking, because seventeen years is long enough to wait for a sentence.\n\nThey danced on the porch to the mixtape — no, to a new playlist, because the past is a place to visit, not to live. Lucy Fairbanks had learned that at last."}, {'n': 6, 'title': 'Epilogue in Wildflowers', 'text': "Years later, a vintage locket sits on the mantel still, a little faded, entirely cherished. The house is full of noise: children, dogs, her best friend Jess's children, the whole beautiful chaos of a life chosen.\n\nLucy Fairbanks walks the shore most evenings, sometimes alone, sometimes with him, always with the lakeside village around her like a held breath. The sunsets haven't changed. She has — into someone who stays.\n\nher best friend Jess still diagnoses everything with pie. Her grandmother Rose's quilt is worn thin with love. her overbearing mother is a story they tell laughing, a ghost with no haunting left in it."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

